        for(auto value:candidates){auto c=value.toObject();auto result=MeshProfiles::decode(source,{},c,cancel,nullptr,nullptr,nullptr,nullptr,nullptr,&session);QVERIFY2(result.mesh,qPrintable(result.error));QVERIFY(result.surface);if(c["objectOffset"]=="414"){QVERIFY(std::abs(result.mesh->vertices.first().position[0]+1038.4465332f)<.001f);QVERIFY(std::abs(result.mesh->vertices.first().uv[0]-567.f*100.f/65535.f)<1e-5f);QVERIFY(std::abs(result.mesh->vertices.first().uv[1]-31.f*100.f/65535.f)<1e-5f);}triangles+=result.mesh->triangles.size()/3;placeholders+=result.surface->material.sourceBindings["unsupportedTexturePlaceholder"].toBool();exports.append({c["name"].toString(),path,result.mesh,result.surface->texture,result.surface->material});}QCOMPARE(triangles,364078);QCOMPARE(session.catalog.nodes,1436);QCOMPARE(std::count_if(session.catalog.draws.cbegin(),session.catalog.draws.cend(),[](const auto &d){return !d.instance;}),14573);QCOMPARE(session.catalog.skipped,0);QCOMPARE(session.images.size(),1190);QCOMPARE(placeholders,0);QTemporaryDir dir;ModelExportOptions options;auto written=exportModel(dir.filePath("barcelona.glb"),exports,options);QVERIFY2(written.ok,qPrintable(written.error));QCOMPARE(written.faces,quint64(triangles));auto destination=qEnvironmentVariable("WORKBENCH_MATERIAL_EXPORT");if(!destination.isEmpty()){auto copy=exportModel(QDir(destination).filePath("PGR2-Barcelona-native.glb"),exports,options);QVERIFY2(copy.ok,qPrintable(copy.error));}cancel=true;QVERIFY(!Pgr2Track::decode(source,{},candidates.first().toObject(),cancel,&session).mesh);qInfo()<<"PGR2 Barcelona base track"<<triangles<<"triangles"<<session.images.size()<<"shared images; GLB export passed";
