    void nfsHuffValidation(){
        auto number=[](quint32 n){QString bits;if(n<4)return QString("1")+QString::number(n,2).rightJustified(2,'0');int width=3;while(n>=(quint32(1)<<(width+1))-4)++width;return QString(width-2,'0')+"1"+QString::number(n-((quint32(1)<<width)-4),2).rightJustified(width,'0');};
        auto fixture=[&](QString body,int size,int mode=0x30fb){QString bits=QString::number(mode,2).rightJustified(16,'0')+QString::number(size,2).rightJustified(24,'0')+QString(8,'1')+number(2)+number(65)+number(189)+body;QByteArray input(16,0);input.replace(0,8,QByteArray::fromHex("4855464601100000"));qToLittleEndian<quint32>(size,input.data()+8);while(bits.size()%8)bits+='0';for(int p=0;p<bits.size();p+=8)input.append(char(bits.mid(p,8).toUInt(nullptr,2)));qToLittleEndian<quint32>(input.size()-16,input.data()+12);return input;};QString end="1"+number(0)+"1",error;auto literal=fixture("00"+end,2);QCOMPARE(NfsHuff::decode(literal,2,error),QByteArray("AA"));auto repeat=fixture("01"+number(8)+end,9);QCOMPARE(NfsHuff::decode(repeat,9,error),QByteArray(9,'A'));auto escaped=fixture("1"+number(0)+"0"+QString::number(66,2).rightJustified(8,'0')+end,1);QCOMPARE(NfsHuff::decode(escaped,1,error),QByteArray("B"));for(int n=0;n<literal.size();++n){QVERIFY(NfsHuff::decode(literal.left(n),2,error).isEmpty());QVERIFY(!error.isEmpty());}QVERIFY(NfsHuff::decode(fixture("1"+number(3)+end,3),3,error).isEmpty());QVERIFY(NfsHuff::decode(fixture("01"+number(8)+end,2),2,error).isEmpty());QVERIFY(NfsHuff::decode(literal,3,error).isEmpty());std::atomic_bool canceled=true;QVERIFY(NfsHuff::decode(literal,2,error,&canceled).isEmpty());QVERIFY(error.contains("canceled"));QCOMPARE(NfsHuff::decode(fixture("00"+end,2,0x32fb),2,error),QByteArray::fromHex("4182"));QCOMPARE(NfsHuff::decode(fixture("00"+end,2,0x34fb),2,error),QByteArray::fromHex("41c3"));
    }
